// Generate an arbitrary status/error code (library accepts both positive and negative domains)
int code = *FUZZ_PARAM(int);

// Call the target function to obtain a const, read-only message pointer
const char *msg = fido_strerr(code);

// Contract expectations:
//  - msg should be a non-null, NUL-terminated C string owned by the library.
//  - We must not modify or free it.
FUZZ_ASSERT(msg != nullptr, "fido_strerr returned null");

// Safely scan for termination with a hard cap to avoid unbounded reads
size_t cap = 1024; // keep small for perf
size_t i = 0;
for (; i < cap && msg[i] != '\0'; i++) {
    // touch the bytes to exercise potential formatting branches and cache lines
}
if (i == cap) {
    // If not NUL-terminated within cap, treat as contract violation or unknown impl; bail
    FUZZ_BAIL();
}

// Record last seen code and a snippet of the message for cross-stub diagnostics/coverage
FUZZ_SET_ATTR_INT_GLOBAL("last_strerr_code", code);
// Store up to first byte only to avoid copying unbounded data
FUZZ_SET_ATTR_INT_GLOBAL("last_strerr_first_char", (int)(unsigned char)msg[0]);

// Allocate a new ES256 public key object
es256_pk_t *es256_pk = es256_pk_new();
// Bail if allocation failed; caller expects a valid, non-null output object
if (!es256_pk) { FUZZ_BAIL(); }
// Track initialization state for downstream stubs (not yet populated with a key)
FUZZ_SET_ATTR_INT(es256_pk, "has_pubkey", 0);
// Validation: Produces a single, non-null es256_pk object and tags it as uninitialized.

// Free an ES256 public key. API expects a pointer-to-pointer; adapt the input accordingly.
es256_pk_t *tmp = es256_pk; // take ownership from the fuzzer runtime for this call
// It's valid to pass a pointer to a NULL inner pointer; here tmp may be non-null.
es256_pk_free(&tmp);
// Do not return the object; it has been freed (or was a no-op if already NULL).
// Validation: Consumes es256_pk and performs es256_pk_free(&ptr) without leaking or double-freeing.

// Convert a populated ES256 public key to an OpenSSL EVP_PKEY.
// Enforce: input key must have been populated successfully by a prior from_* operation.
int has_pub = FUZZ_GET_ATTR_INT(es256_pk, "has_pubkey");
if (!has_pub) { FUZZ_BAIL(); }
// Perform the conversion.
EVP_PKEY *p = es256_pk_to_EVP_PKEY(es256_pk);
if (!p) { FUZZ_BAIL(); } // treat conversion failure as an error to avoid returning a null output
// Hand the resulting pointer back to the runtime as an opaque handle.
void *evp_pkey = (void *)p;
// Track type metadata so other stubs can validate correct usage of this opaque pointer.
FUZZ_SET_ATTR_STR(evp_pkey, "objtype", "EVP_PKEY");
FUZZ_SET_ATTR_PTR(evp_pkey, "derived_from", (void *)es256_pk);
// Validation: Requires has_pubkey==1, returns both original es256_pk and a non-null EVP_PKEY handle with type metadata.

// Populate an ES256 public key from an existing OpenSSL EVP_PKEY.
// Validate that the provided opaque pointer is indeed an EVP_PKEY produced by our harness.
const char *t = FUZZ_GET_ATTR_STR(evp_pkey, "objtype");
if (!t || t[0] == '\0') { FUZZ_BAIL(); }
int is_evp = (t[0]=='E' && t[1]=='V' && t[2]=='P'); // cheap check for "EVP_PKEY"
if (!is_evp) { FUZZ_BAIL(); }
// Call the target function. Ownership of EVP_PKEY remains with caller; keep it in outputs.
int rc = es256_pk_from_EVP_PKEY(es256_pk, (const EVP_PKEY *)evp_pkey);
// On apparent success (conventionally rc==0), mark the key as populated.
if (rc == 0) {
    FUZZ_SET_ATTR_INT(es256_pk, "has_pubkey", 1);
}
// Return both objects since neither is freed here.
// Validation: Ensures correct source object type via attribute, updates has_pubkey on success, and preserves both inputs as outputs.

// Populate an ES256 public key from a raw byte buffer.
// Generate a fuzz buffer; size is [1,4096]. The library will validate actual encoding.
std::string buf = FUZZ_PARAM_STR();
// Guard against undefined behavior: if size is zero (shouldn't happen per runtime), bail.
if (buf.size() == 0) { FUZZ_BAIL(); }
int rc = es256_pk_from_ptr(es256_pk, (const void *)buf.data(), (size_t)buf.size());
// If the parse/conversion appears successful, mark the key as populated for downstream use.
if (rc == 0) {
    FUZZ_SET_ATTR_INT(es256_pk, "has_pubkey", 1);
}
// Keep the key in the pool for future operations.
// Validation: Safely exercises success/failure paths and sets has_pubkey only when rc==0.

// Allocate a new ES384 public key container and validate allocation
es384_pk_t *pk = es384_pk_new();
if (!pk) {
    // Allocation failed; abort this stub to avoid null deref or misuse
    FUZZ_BAIL();
}
// Track lifecycle and initialization state for downstream stubs
FUZZ_SET_ATTR_INT(pk, "es384.alloc", 1);
FUZZ_SET_ATTR_INT(pk, "es384.init", 0);
// pk is returned as a persistent output object

// Free an ES384 public key. The API expects es384_pk_t **.
// We received ownership of pk from the object pool. Do not return it after free.
if (!pk) {
    FUZZ_BAIL();
}
// Clear attributes to avoid stale state in case implementation doesn't null the pointer
FUZZ_SET_ATTR_INT(pk, "es384.alloc", 0);
FUZZ_SET_ATTR_INT(pk, "es384.init", 0);
// Invoke free with a pointer-to-pointer as required by the API
es384_pk_t *tmp = pk; // take local copy so we can pass its address
es384_pk_free(&tmp);
// Drop the object by not listing any outputs

// Convert an initialized ES384 public key to an OpenSSL EVP_PKEY.
// Enforce that pk is initialized from a successful import (e.g., from_ptr or from_EVP_PKEY).
int is_init = FUZZ_GET_ATTR_INT(pk, "es384.init");
if (!is_init) {
    // Conversion requires a valid initialized key
    FUZZ_BAIL();
}
EVP_PKEY *pkey = es384_pk_to_EVP_PKEY(pk);
// Caller must check for NULL per API; if NULL, bail to keep usage valid and avoid leaking unknown state
if (!pkey) {
    FUZZ_BAIL();
}
// Tag the produced EVP_PKEY so it can be safely consumed by es384_pk_from_EVP_PKEY
FUZZ_SET_ATTR_STR(pkey, "origin", "EVP_ES384");
// Return both pk (still owned/persistent) and the produced pkey for reuse in other stubs

// Populate an ES384 public key from an EVP_PKEY. Ensure EVP_PKEY is suitable.
if (!pk || !pkey) {
    FUZZ_BAIL();
}
// Require that pkey originated from an ES384 conversion to maximize correctness
const char *src = FUZZ_GET_ATTR_STR(pkey, "origin");
int ok_src = (src && src[0] != '\0');
if (!ok_src) {
    FUZZ_BAIL();
}
int rc = es384_pk_from_EVP_PKEY(pk, pkey);
// Caller must check return; consider 0 as success (conventional). Only mark initialized on success.
if (rc == 0) {
    FUZZ_SET_ATTR_INT(pk, "es384.alloc", 1);
    FUZZ_SET_ATTR_INT(pk, "es384.init", 1);
} else {
    // Leave pk state unchanged on failure to avoid misrepresenting initialization
    FUZZ_BAIL();
}
// Return both objects; pk remains in use and pkey can be reused elsewhere

// Parse a raw buffer into an ES384 public key. The exact encoding is library-defined.
if (!pk) {
    FUZZ_BAIL();
}
// Generate a candidate buffer. Prefer typical uncompressed P-384 point size (97 bytes) occasionally.
std::string buf = FUZZ_PARAM_STR();
unsigned want97 = (unsigned)(*FUZZ_PARAM(unsigned int) % 3u); // ~1/3 try canonical size
if (want97 == 0) {
    // Resize to 97 bytes to increase chance of a successful parse (0x04 || X(48) || Y(48))
    if (buf.size() != 97) buf.resize(97, '\0');
}
int rc = es384_pk_from_ptr(pk, (const void *)buf.data(), (size_t)buf.size());
// Mark initialization only on success (assume 0 == success by convention). If failure, keep pk as allocated-only.
if (rc == 0) {
    FUZZ_SET_ATTR_INT(pk, "es384.alloc", 1);
    FUZZ_SET_ATTR_INT(pk, "es384.init", 1);
} else {
    // Parsing failed: do not mark initialized. This is an allowed outcome; keep pk for future attempts.
}
// Return pk as output so it persists for further operations

// Allocate a new EDDSA public key container.
eddsa_pk_t *eddsa_pk = eddsa_pk_new();
// Enforce allocation success as this stub intends to return a persistent object.
if (!eddsa_pk) { FUZZ_BAIL(); }
// Track initialization state: container exists but has no key material yet.
FUZZ_SET_ATTR_INT(eddsa_pk, "has_material", 0);
// Validation: returns a non-null handle and marks it as lacking material until populated.

// Free the EDDSA public key object and null the caller's pointer.
// It is safe if eddsa_pk is already NULL; the function will be a no-op.
eddsa_pk_free(&eddsa_pk);
// Do not return the freed object. Validation: object ownership relinquished; no outputs are produced.

// Convert an initialized EDDSA public key to an OpenSSL EVP_PKEY.
// Require that the eddsa_pk has been populated with key material first.
int has_material = FUZZ_GET_ATTR_INT(eddsa_pk, "has_material");
