// If conversion failed, bail to avoid emitting a null output pointer.
if (!pkey) { FUZZ_BAIL(); }
// Keep eddsa_pk alive for further use; return both objects.
// Validation: enforces initialized input; bails on conversion failure; returns non-null EVP_PKEY.

// Populate an EDDSA key from an existing EVP_PKEY.
// Both pointers must be non-null; the fuzzer runtime guarantees non-null variables.
int rc = eddsa_pk_from_EVP_PKEY(eddsa_pk, pkey);
// On success, mark the EDDSA key as having material.
if (rc == 0) {
    FUZZ_SET_ATTR_INT(eddsa_pk, "has_material", 1);
} else {
    // If population fails, bail to avoid leaving callers assuming success.
    FUZZ_BAIL();
