import random
import struct
import string
from typing import Tuple

# This generator builds a valid-ish WebAuthn attestation object (attObj):
# CBOR map { "fmt": tstr, "authData": bstr, "attStmt": map }
# It focuses on producing syntactically valid CBOR with reasonable values so that
# libfido2 can parse authData and potentially expose a COSE public key via
# fido_cred_pubkey_ptr/len when the internal decoder accepts it.
#
# authData structure (without extensions beyond attestedCredData):
# - rpIdHash: 32 bytes SHA256(rpId) placeholder (random bytes)
# - flags: 1 byte (bit 6 AT flag set to include attested credential data)
# - signCount: 4 bytes
# - attestedCredData:
#   - aaguid: 16 bytes
#   - credentialIdLength: 2 bytes (big endian)
#   - credentialId: variable
#   - credentialPublicKey: COSE_Key (CBOR map) for ES256/ES384/EdDSA/RS256
#
# attStmt depends on fmt; we produce simple plausible maps.

# Minimal CBOR helpers (only what we need):

MAJOR_TYPE_UINT = 0
MAJOR_TYPE_BSTR = 2
MAJOR_TYPE_TSTR = 3
MAJOR_TYPE_ARRAY = 4
MAJOR_TYPE_MAP = 5


def _cbor_hdr(major: int, ai: int) -> bytes:
    return bytes([(major << 5) | ai])


def _cbor_uint(n: int) -> bytes:
    if n < 0:
        raise ValueError("uint must be >= 0")
    if n < 24:
        return _cbor_hdr(MAJOR_TYPE_UINT, n)
    if n < 256:
        return _cbor_hdr(MAJOR_TYPE_UINT, 24) + struct.pack("!B", n)
    if n < 65536:
        return _cbor_hdr(MAJOR_TYPE_UINT, 25) + struct.pack("!H", n)
    if n < 4294967296:
        return _cbor_hdr(MAJOR_TYPE_UINT, 26) + struct.pack("!I", n)
    return _cbor_hdr(MAJOR_TYPE_UINT, 27) + struct.pack("!Q", n)


def _cbor_bstr(b: bytes) -> bytes:
    l = len(b)
    if l < 24:
        return _cbor_hdr(MAJOR_TYPE_BSTR, l) + b
    if l < 256:
        return _cbor_hdr(MAJOR_TYPE_BSTR, 24) + struct.pack("!B", l) + b
    if l < 65536:
        return _cbor_hdr(MAJOR_TYPE_BSTR, 25) + struct.pack("!H", l) + b
    return _cbor_hdr(MAJOR_TYPE_BSTR, 26) + struct.pack("!I", l) + b


def _cbor_tstr(s: str) -> bytes:
    b = s.encode("utf-8")
    l = len(b)
    if l < 24:
        return _cbor_hdr(MAJOR_TYPE_TSTR, l) + b
    if l < 256:
        return _cbor_hdr(MAJOR_TYPE_TSTR, 24) + struct.pack("!B", l) + b
    if l < 65536:
        return _cbor_hdr(MAJOR_TYPE_TSTR, 25) + struct.pack("!H", l) + b
    return _cbor_hdr(MAJOR_TYPE_TSTR, 26) + struct.pack("!I", l) + b


def _cbor_map(pairs: Tuple[Tuple[bytes, bytes], ...]) -> bytes:
    l = len(pairs)
    if l < 24:
        out = _cbor_hdr(MAJOR_TYPE_MAP, l)
    elif l < 256:
        out = _cbor_hdr(MAJOR_TYPE_MAP, 24) + struct.pack("!B", l)
    elif l < 65536:
        out = _cbor_hdr(MAJOR_TYPE_MAP, 25) + struct.pack("!H", l)
    else:
        out = _cbor_hdr(MAJOR_TYPE_MAP, 26) + struct.pack("!I", l)
    for k, v in pairs:
        out += k + v
    return out


def _rand_bytes(r: random.Random, n: int) -> bytes:
    return bytes(r.getrandbits(8) for _ in range(n))


# Build COSE Key variants. Use canonical keys and valid sizes.
# COSE common labels: 1:kty, 3:alg, -1:crv, -2:x, -3:y, -1: n (RSA), -2: e (RSA)
# Values follow RFC8152/RFC9052 conventions; alg values: ES256(-7), ES384(-35), EdDSA(-8), RS256(-257)

COSE_KTY_OKP = 1
COSE_KTY_EC2 = 2
COSE_KTY_RSA = 3

ALG_ES256 = -7
ALG_ES384 = -35
ALG_EDDSA = -8
ALG_RS256 = -257

CRV_P256 = 1
CRV_P384 = 2
CRV_ED25519 = 6


def _cbor_negint(n_abs: int) -> bytes:
    # encodes negative integer -1 - n_abs per CBOR rules
    # we only need for small negative labels in maps; labels themselves are CBOR integers (can be negative)
    # This function is for values, not labels. For labels, we encode as integers directly within the map constructor.
    # We won't need negative integer values here; keep for completeness.
    if n_abs < 24:
        return _cbor_hdr(1, n_abs)
    if n_abs < 256:
        return _cbor_hdr(1, 24) + struct.pack("!B", n_abs)
    if n_abs < 65536:
        return _cbor_hdr(1, 25) + struct.pack("!H", n_abs)
    if n_abs < 4294967296:
        return _cbor_hdr(1, 26) + struct.pack("!I", n_abs)
    return _cbor_hdr(1, 27) + struct.pack("!Q", n_abs)


def _cbor_int(n: int) -> bytes:
    if n >= 0:
        return _cbor_uint(n)
    # CBOR negative integers are (major type 1) with value = -1 - n
    return _cbor_negint(-1 - n)


def _cose_ec2_key(r: random.Random, curve: int) -> bytes:
    if curve == CRV_P256:
        alg = ALG_ES256
        x = _rand_bytes(r, 32)
        y = _rand_bytes(r, 32)
    else:
        alg = ALG_ES384
        x = _rand_bytes(r, 48)
        y = _rand_bytes(r, 48)
    pairs = (
        (_cbor_int(1), _cbor_int(COSE_KTY_EC2)),
        (_cbor_int(3), _cbor_int(alg)),
        (_cbor_int(-1), _cbor_int(curve)),
        (_cbor_int(-2), _cbor_bstr(x)),
        (_cbor_int(-3), _cbor_bstr(y)),
    )
    return _cbor_map(pairs)


def _cose_okp_ed25519(r: random.Random) -> bytes:
    x = _rand_bytes(r, 32)
    pairs = (
        (_cbor_int(1), _cbor_int(COSE_KTY_OKP)),
        (_cbor_int(3), _cbor_int(ALG_EDDSA)),
        (_cbor_int(-1), _cbor_int(CRV_ED25519)),
        (_cbor_int(-2), _cbor_bstr(x)),
    )
    return _cbor_map(pairs)


def _cose_rsa256(r: random.Random) -> bytes:
    # 2048-bit modulus, small exponent (65537)
    n = bytearray(_rand_bytes(r, 256))
    # Ensure high bit set so it's clearly 2048-bit length
    n[0] |= 0x80
    e = (65537).to_bytes(3, 'big')
    pairs = (
        (_cbor_int(1), _cbor_int(COSE_KTY_RSA)),
        (_cbor_int(3), _cbor_int(ALG_RS256)),
        (_cbor_int(-1), _cbor_bstr(bytes(n))),
        (_cbor_int(-2), _cbor_bstr(e)),
    )
    return _cbor_map(pairs)


def _build_authdata_with_attested_cred(r: random.Random) -> bytes:
    rp_id_hash = _rand_bytes(r, 32)
    # Flags: UP (0x01) set optionally, AT (0x40) must be set to include attested cred data.
    flags = 0x40 | (0x01 if r.random() < 0.5 else 0)
    sigcount = r.randrange(0, 2**32)
    auth_fixed = rp_id_hash + struct.pack('!B', flags) + struct.pack('!I', sigcount)

    aaguid = _rand_bytes(r, 16)
    cred_id_len = r.randrange(16, 64)  # typical credential ID sizes vary; keep moderate
    cred_id = _rand_bytes(r, cred_id_len)

    # Pick a COSE key type at random to diversify coverage
    choice = r.choice(['es256', 'es384', 'eddsa', 'rs256'])
    if choice == 'es256':
        cose_key = _cose_ec2_key(r, CRV_P256)
    elif choice == 'es384':
        cose_key = _cose_ec2_key(r, CRV_P384)
    elif choice == 'eddsa':
        cose_key = _cose_okp_ed25519(r)
    else:
        cose_key = _cose_rsa256(r)

    attested = (
        aaguid + struct.pack('!H', cred_id_len) + cred_id + cose_key
    )
    return auth_fixed + attested


def _build_attstmt_and_fmt(r: random.Random) -> Tuple[str, bytes]:
    # Provide simple attStmt variants compatible with common formats.
    # packed: { alg: -7, sig: bstr, x5c: [ bstr ] } or minimal {sig}
    # none: {}
    # tpm often complex; we avoid it for brevity.
    fmt = r.choice(["packed", "none"]) if r.random() < 0.85 else "packed"
    if fmt == "none":
        attstmt = _cbor_map(tuple())
        return fmt, attstmt

    # packed
    sig = _rand_bytes(r, r.randrange(64, 80))  # ECDSA sig sizes vary; DER not required here
    # 70% include x5c one-cert chain; otherwise leave only alg+sig
    include_x5c = r.random() < 0.7
    pairs = [(_cbor_tstr("alg"), _cbor_int(r.choice([ALG_ES256, ALG_ES384, ALG_RS256, ALG_EDDSA]))) ,
             (_cbor_tstr("sig"), _cbor_bstr(sig))]
    if include_x5c:
        # Minimal one certificate placeholder bytes
        cert = _rand_bytes(r, r.randrange(200, 600))
        # Build CBOR array manually: [ bstr(cert) ]
        arr = _cbor_hdr(MAJOR_TYPE_ARRAY, 1) + _cbor_bstr(cert)
        pairs.append((_cbor_tstr("x5c"), arr))
    attstmt = _cbor_map(tuple(pairs))
    return "packed", attstmt


def _build_attobj(r: random.Random) -> bytes:
    fmt, attstmt = _build_attstmt_and_fmt(r)
    authdata = _build_authdata_with_attested_cred(r)

    pairs = (
        (_cbor_tstr("fmt"), _cbor_tstr(fmt)),
        (_cbor_tstr("authData"), _cbor_bstr(authdata)),
        (_cbor_tstr("attStmt"), attstmt),
    )
    return _cbor_map(pairs)


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Randomize a bit more per call with a jump from the base seed
    # to produce varied outputs for different consumers/seeds while staying deterministic per seed.
    _ = r.random()
    attobj = _build_attobj(r)
    # Guarantee upper bound on size
    if len(attobj) > 4096:
        # In unlikely case, rebuild with simpler choices
        r2 = random.Random(seed ^ 0xA5A5)
        attobj = _build_attobj(r2)
        attobj = attobj[:4096]
    return attobj

import os
import random
import struct
import hashlib

# This generator produces valid-looking attestation signatures in common encodings
# used by WebAuthn/FIDO2 attestation statements:
# - ECDSA (ES256/ES384) signatures encoded as ASN.1 DER (r,s) integers
# - RSA PKCS#1 v1.5 signatures (random-looking blob of appropriate size)
# - Ed25519 raw 64-byte signatures
# The fuzz stubs only require non-empty buffers and do not verify cryptography,
# but valid encodings help exercise parsing/length logic in downstream code.

MAX_OUT = 4096

# Minimal DER helpers for ECDSA signature (SEQUENCE of two INTEGERs)

def _der_encode_integer(x: int) -> bytes:
    # big-endian without leading zeros; if high bit set, prefix 0x00
    if x == 0:
        content = b"\x00"
    else:
        blen = (x.bit_length() + 7) // 8
        content = x.to_bytes(blen, 'big')
        if content[0] & 0x80:
            content = b"\x00" + content
    return b"\x02" + _der_len(len(content)) + content


def _der_len(n: int) -> bytes:
    if n < 0x80:
        return bytes([n])
    b = n.to_bytes((n.bit_length()+7)//8, 'big')
    return bytes([0x80 | len(b)]) + b


def _der_sequence(elements: list[bytes]) -> bytes:
    content = b"".join(elements)
    return b"\x30" + _der_len(len(content)) + content


def _randbits(rng: random.Random, bits: int) -> int:
    # Generate a random integer in [1, 2^bits-1]
    if bits <= 0:
        return 0
    x = rng.getrandbits(bits)
    if x == 0:
        x = 1
    # mask down to bits
    x &= (1 << bits) - 1
    if x == 0:
        x = 1
    return x


def gen_ecdsa_der(rng: random.Random, curve: str = "P-256") -> bytes:
    # Choose bit length per curve
    bits = 256 if curve == "P-256" else 384
    # Produce r,s uniformly in [1, n-1] approximation by bits
    r = _randbits(rng, bits)
    s = _randbits(rng, bits)
    return _der_sequence([_der_encode_integer(r), _der_encode_integer(s)])


def gen_rsa_pkcs1_v15(rng: random.Random, bits: int = 2048) -> bytes:
    # Produce a blob with plausible PKCS#1 v1.5 structure: 0x00 0x01 0xFF... 0x00 || digestInfo || mhash
    # We do not compute a real signature; this is structurally valid-looking and fixed size.
    k = bits // 8
    # pick a random hash to embed (SHA-256 or SHA-384) via DigestInfo prefix
    # ASN.1 DigestInfo for SHA-256: 0x3031300d060960864801650304020105000420 || H
    # ASN.1 DigestInfo for SHA-384: 0x3041300d060960864801650304020205000430 || H
    msg = rng.randbytes(rng.randrange(16, 128))
    if rng.random() < 0.5:
        oid_prefix = bytes.fromhex("3031300d060960864801650304020105000420")
        H = hashlib.sha256(msg).digest()
    else:
        oid_prefix = bytes.fromhex("3041300d060960864801650304020205000430")
        H = hashlib.sha384(msg).digest()
    t = oid_prefix + H
    # Build EMSA-PKCS1-v1_5 block: 0x00 0x01 PS 0x00 T where PS is 0xFF repeated
    # Ensure space for header and T
    ps_len = max(8, k - 3 - len(t))
    if ps_len < 8:
        # fallback: just produce random if constraints impossible
        return rng.randbytes(k)
    ps = b"\xff" * ps_len
    em = b"\x00\x01" + ps + b"\x00" + t
    if len(em) < k:
        em = em + b"\x00" * (k - len(em))
    return em[:k]


def gen_ed25519_raw(rng: random.Random) -> bytes:
    # Ed25519 signatures are 64 bytes (R(32) || S(32)). We provide random 64 bytes.
    return rng.randbytes(64)


def gen_misc_binary(rng: random.Random) -> bytes:
    # Produce other plausible signature sizes to exercise length handling (bounded by 512 in stubs)
    choices = [
        70, 71, 72, 73, 74,  # common ECDSA DER lengths
        256, 257, 258,       # RSA-2048 near sizes
        384, 385,            # RSA-3072 near sizes
        64,                  # Ed25519
        112,                 # ES384 DER upper-bound-ish
    ]
    n = rng.choice(choices)
    return rng.randbytes(n)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Select a signature style with weighted probabilities
    style = rng.choices(
        population=["es256", "es384", "rsa2048", "ed25519", "misc"],
        weights=[35, 15, 25, 15, 10],
        k=1,
    )[0]

    if style == "es256":
        data = gen_ecdsa_der(rng, "P-256")
    elif style == "es384":
        data = gen_ecdsa_der(rng, "P-384")
    elif style == "rsa2048":
        data = gen_rsa_pkcs1_v15(rng, 2048)
    elif style == "ed25519":
        data = gen_ed25519_raw(rng)
    else:
        data = gen_misc_binary(rng)

    # Bound final size to what stubs will accept/use and global limit
    if len(data) > 512:
        data = data[:512]
    if len(data) == 0:
        data = b"\x00"
    if len(data) > MAX_OUT:
        data = data[:MAX_OUT]
    return data

import random
import struct
from typing import List, Tuple

# We need to generate CBOR-encoded attestation statement (attStmt) maps
# that are valid and likely to be parsed by libfido2 for fields like:
#  - alg (COSE algorithm number)
#  - sig (signature bytes)
#  - x5c (array of DER certificates)
# Possibly other formats: packed, tpm, android-key/safetynet; but for the
# targeted fuzz stubs, the interesting part is presence of x5c and attStmt len.
#
# Strategy:
#  - Build several variants of attStmt maps:
#     1) packed with x5c array containing one or more plausible DER cert blobs
#     2) packed with only sig/alg (no x5c) to exercise count==0 paths
#     3) packed with x5c chain of 2-3 certificates
#  - DER certificates: we will craft syntactically plausible ASN.1 DER SEQUENCE
#    with nested sequences to look like an X.509 cert. They won't be valid, but
#    should be well-formed TLV so the library can treat as opaque cert bytes.
#  - CBOR encoding implemented minimally for needed types.
#
#  Note: We must return a single bytes buffer. The fuzz harness will call
#  FUZZ_PARAM_STR multiple times. To help, we concatenate multiple CBOR maps
#  separated by a CBOR break in a top-level array, so splitting arbitrary may
#  still yield valid first element. However, harness pulls strings independently.
#  Instead, we will produce one attStmt map that is self-contained and valid.
#
#  We randomize chain length and sizes within 4k limit.

# Minimal CBOR utilities

def cbor_uint(n: int) -> bytes:
    assert n >= 0
    if n < 24:
        return bytes([0x00 | n])
    elif n < 256:
        return bytes([0x18, n])
    elif n < 65536:
        return bytes([0x19]) + struct.pack('>H', n)
    elif n < 4294967296:
        return bytes([0x1a]) + struct.pack('>I', n)
    else:
        return bytes([0x1b]) + struct.pack('>Q', n)


def cbor_negint(n: int) -> bytes:
    # encodes negative integer -1 - n
    assert n >= 0
    if n < 24:
        return bytes([0x20 | n])
    elif n < 256:
        return bytes([0x38, n])
    elif n < 65536:
        return bytes([0x39]) + struct.pack('>H', n)
    elif n < 4294967296:
        return bytes([0x3a]) + struct.pack('>I', n)
    else:
        return bytes([0x3b]) + struct.pack('>Q', n)


def cbor_bytes(b: bytes) -> bytes:
    l = len(b)
    if l < 24:
        return bytes([0x40 | l]) + b
    elif l < 256:
        return bytes([0x58, l]) + b
    elif l < 65536:
        return bytes([0x59]) + struct.pack('>H', l) + b
    elif l < 4294967296:
        return bytes([0x5a]) + struct.pack('>I', l) + b
    else:
        return bytes([0x5b]) + struct.pack('>Q', l) + b


def cbor_text(s: str) -> bytes:
    b = s.encode('utf-8')
    l = len(b)
    if l < 24:
        return bytes([0x60 | l]) + b
    elif l < 256:
        return bytes([0x78, l]) + b
    elif l < 65536:
        return bytes([0x79]) + struct.pack('>H', l) + b
    elif l < 4294967296:
        return bytes([0x7a]) + struct.pack('>I', l) + b
    else:
        return bytes([0x7b]) + struct.pack('>Q', l) + b


def cbor_array(items: List[bytes]) -> bytes:
    l = len(items)
    if l < 24:
        head = bytes([0x80 | l])
    elif l < 256:
        head = bytes([0x98, l])
    elif l < 65536:
        head = bytes([0x99]) + struct.pack('>H', l)
    else:
        head = bytes([0x9a]) + struct.pack('>I', l)
    return head + b''.join(items)


def cbor_map(pairs: List[Tuple[bytes, bytes]]) -> bytes:
    l = len(pairs)
    if l < 24:
        head = bytes([0xa0 | l])
    elif l < 256:
        head = bytes([0xb8, l])
    elif l < 65536:
        head = bytes([0xb9]) + struct.pack('>H', l)
    else:
        head = bytes([0xba]) + struct.pack('>I', l)
    body = b''.join(k + v for k, v in pairs)
    return head + body


# ASN.1 DER helpers to craft plausible X.509-looking certs

def der_len(l: int) -> bytes:
    if l < 0x80:
        return bytes([l])
    s = []
    while l > 0:
        s.append(l & 0xff)
        l >>= 8
    s.reverse()
    return bytes([0x80 | len(s)]) + bytes(s)


def der_tlv(tag: int, content: bytes) -> bytes:
    return bytes([tag]) + der_len(len(content)) + content


def der_sequence(sub: List[bytes]) -> bytes:
    content = b''.join(sub)
    return der_tlv(0x30, content)


def der_integer_of_length(nbytes: int, rnd: random.Random) -> bytes:
    # Ensure first bit not interpreted as negative: add leading 0x00 if high bit set
    val = bytearray(rnd.getrandbits(8) for _ in range(max(1, nbytes)))
    if val and (val[0] & 0x80):
        val = bytearray([0x00]) + val
    return der_tlv(0x02, bytes(val))


def der_bitstring(data: bytes) -> bytes:
    # prepend unused-bits count byte
    return der_tlv(0x03, bytes([0x00]) + data)


def der_octet_string(data: bytes) -> bytes:
    return der_tlv(0x04, data)


def der_null() -> bytes:
    return der_tlv(0x05, b"")


def der_oid(oid_bytes: bytes) -> bytes:
    return der_tlv(0x06, oid_bytes)


def oid_from_str(oid: str) -> bytes:
    # Basic BER OID encoder sufficient for common OIDs
    parts = list(map(int, oid.split('.')))
    if len(parts) < 2:
        return b"\x06\x01\x00"  # fallback
    first = 40 * parts[0] + parts[1]
    out = [first]
    for p in parts[2:]:
        # base-128
        stack = [p & 0x7f]
        p >>= 7
        while p:
            stack.append(0x80 | (p & 0x7f))
            p >>= 7
        out.extend(reversed(stack))
    content = bytes(out)
    return der_tlv(0x06, content)


def make_plausible_cert(rnd: random.Random, key_type: str = "EC") -> bytes:
    # Version (v3) [0] EXPLICIT INTEGER 2
    version = der_tlv(0xa0, der_integer_of_length(1, rnd))
    serial = der_integer_of_length(rnd.randint(8, 16), rnd)
    # Signature algorithm: sha256WithRSAEncryption or ecdsa-with-SHA256
    if key_type == "RSA":
        sigalg = der_sequence([oid_from_str("1.2.840.113549.1.1.11"), der_null()])
        spki_alg = der_sequence([oid_from_str("1.2.840.113549.1.1.1"), der_null()])
        # RSAPublicKey SEQUENCE { modulus INTEGER, exponent INTEGER }
        modulus = der_integer_of_length(256, rnd)
        exponent = der_integer_of_length(3, rnd)
        pubkey_inner = der_sequence([modulus, exponent])
        spki = der_sequence([spki_alg, der_bitstring(pubkey_inner)])
    else:
        sigalg = der_sequence([oid_from_str("1.2.840.10045.4.3.2")])  # ecdsa-with-SHA256
        # id-ecPublicKey with P-256
        spki_alg = der_sequence([oid_from_str("1.2.840.10045.2.1"), oid_from_str("1.2.840.10045.3.1.7")])
        # Uncompressed EC point 0x04 || X || Y, 32-byte coords
        point = bytes([0x04]) + bytes(rnd.getrandbits(8) for _ in range(64))
        spki = der_sequence([spki_alg, der_bitstring(point)])

    # Issuer/Subject (very simple): SEQUENCE of RDNs with CN
    at_cn = der_sequence([oid_from_str("2.5.4.3"), der_tlv(0x0c, b"Fuzz CA")])  # UTF8String
    issuer = der_sequence([der_set := der_tlv(0x31, at_cn)])
    subject = der_sequence([der_set])

    # Validity: notBefore/NotAfter as GeneralizedTime strings
    def gentime():
        # YYYYMMDDHHMMSSZ
        y = rnd.randint(2020, 2035)
        m = rnd.randint(1, 12)
        d = rnd.randint(1, 28)
        h = rnd.randint(0, 23)
        M = rnd.randint(0, 59)
        s = rnd.randint(0, 59)
        return f"{y:04d}{m:02d}{d:02d}{h:02d}{M:02d}{s:02d}Z".encode()
    nb = der_tlv(0x18, gentime())
    na = der_tlv(0x18, gentime())
    validity = der_sequence([nb, na])

    tbs = der_sequence([
        version,
        serial,
        sigalg,
        issuer,
        validity,
        subject,
        spki,
    ])

    # Signature value BIT STRING (fake)
    sig_bytes = bytes(rnd.getrandbits(8) for _ in range(rnd.randint(64, 96)))
    certificate = der_sequence([
        tbs,
        sigalg,
        der_bitstring(sig_bytes),
    ])
    return certificate


def make_x5c_array(rnd: random.Random) -> List[bytes]:
    chain_len = rnd.choice([1, 2, 3])
    key_type = rnd.choice(["EC", "RSA"])  # mix types to exercise parsers
    certs = [make_plausible_cert(rnd, key_type=key_type) for _ in range(chain_len)]
    return certs


def make_sig(rnd: random.Random, alg: int) -> bytes:
    # Produce a plausible signature blob matching alg family length
    if alg in (-7,):  # ES256
        # DER ECDSA signature: SEQUENCE(INTEGER r, INTEGER s)
        r = der_integer_of_length(32, rnd)
        s = der_integer_of_length(32, rnd)
        return der_sequence([r, s])
    elif alg in (-35,):  # ES384
        r = der_integer_of_length(48, rnd)
        s = der_integer_of_length(48, rnd)
        return der_sequence([r, s])
    elif alg in (-257,):  # RS256
        return bytes(rnd.getrandbits(8) for _ in range(256))
    else:
        # default length
        return bytes(rnd.getrandbits(8) for _ in range(64))


def cbor_int(n: int) -> bytes:
    if n >= 0:
        return cbor_uint(n)
    else:
        return cbor_negint(-1 - n)


def build_attstmt_packed_with_x5c(rnd: random.Random) -> bytes:
    # alg: choose among ES256 (-7), ES384 (-35), RS256 (-257)
    alg = rnd.choice([-7, -35, -257])
    sig = make_sig(rnd, alg)
    x5c_der_list = make_x5c_array(rnd)
    x5c_cbor = cbor_array([cbor_bytes(c) for c in x5c_der_list])

    pairs = [
        (cbor_text("alg"), cbor_int(alg)),
        (cbor_text("sig"), cbor_bytes(sig)),
        (cbor_text("x5c"), x5c_cbor),
    ]
    return cbor_map(pairs)


def build_attstmt_packed_sig_only(rnd: random.Random) -> bytes:
    alg = rnd.choice([-7, -35, -257])
    sig = make_sig(rnd, alg)
    pairs = [
        (cbor_text("alg"), cbor_int(alg)),
        (cbor_text("sig"), cbor_bytes(sig)),
    ]
    return cbor_map(pairs)


def build_attstmt_tpm_like(rnd: random.Random) -> bytes:
    # Minimal TPM-like attStmt keys often include: alg, sig, x5c, certInfo, pubArea
    alg = -257  # RSA typical for TPM
    sig = make_sig(rnd, alg)
    certs = make_x5c_array(rnd)
    x5c_cbor = cbor_array([cbor_bytes(c) for c in certs])
    # Fake certInfo/pubArea blobs (opaque to attstmt_len/x5c consumers)
    certinfo = bytes(rnd.getrandbits(8) for _ in range(rnd.randint(64, 128)))
    pubarea = bytes(rnd.getrandbits(8) for _ in range(rnd.randint(64, 128)))
    pairs = [
        (cbor_text("alg"), cbor_int(alg)),
        (cbor_text("sig"), cbor_bytes(sig)),
        (cbor_text("x5c"), x5c_cbor),
        (cbor_text("certInfo"), cbor_bytes(certinfo)),
        (cbor_text("pubArea"), cbor_bytes(pubarea)),
    ]
    return cbor_map(pairs)


def choose_variant(rnd: random.Random) -> bytes:
    builders = [
        build_attstmt_packed_with_x5c,
        build_attstmt_packed_sig_only,
        build_attstmt_tpm_like,
    ]
    # Weighted to favor x5c presence to exercise x5c_list_* stubs
    weights = [0.6, 0.15, 0.25]
    x = rnd.random()
    acc = 0.0
    for b, w in zip(builders, weights):
        acc += w
        if x <= acc:
            return b(rnd)
    return builders[0](rnd)


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)
    att = choose_variant(rnd)
    # Ensure within size constraints
    if len(att) > 4096:
        # fallback: simple packed sig-only
        att = build_attstmt_packed_sig_only(rnd)
    return att

import random
import struct
import hashlib
from typing import List, Tuple

# This generator produces a valid-looking WebAuthn authenticator data (authData)
# in parsed/wire format as expected by libfido2 setters that take parsed authdata.
# Layout (CTAP2/WebAuthn):
# rpIdHash(32) | flags(1) | signCount(4, big-endian) | [attestedCredentialData if AT flag] | [extensions if ED flag]
# attestedCredentialData: AAGUID(16) | credIdLen(2, big-endian) | credId(credIdLen) | publicKey(COSE Key, CBOR map)
# extensions: CBOR map
# We keep CBOR minimal but well-formed for both the COSE key and extensions to exercise parsing paths.

# Flags bits
# UP 0x01, UV 0x04, AT 0x40, ED 0x80

# Minimal CBOR helpers (enough for our needs)

DEF_MAJOR_TYPE_POSINT = 0
DEF_MAJOR_TYPE_BYTES = 2
DEF_MAJOR_TYPE_TEXT = 3
DEF_MAJOR_TYPE_ARRAY = 4
DEF_MAJOR_TYPE_MAP = 5
DEF_MAJOR_TYPE_TAG = 6
DEF_MAJOR_TYPE_SIMPLE = 7

def _cbor_head(major: int, val: int) -> bytes:
    ai = 0
    if val < 24:
        return bytes([ (major << 5) | val ])
    elif val < 256:
        return bytes([ (major << 5) | 24, val & 0xFF ])
    elif val < 65536:
        return bytes([ (major << 5) | 25 ]) + struct.pack('>H', val)
    elif val < 4294967296:
        return bytes([ (major << 5) | 26 ]) + struct.pack('>I', val)
    else:
        return bytes([ (major << 5) | 27 ]) + struct.pack('>Q', val)

def cbor_uint(n: int) -> bytes:
    return _cbor_head(DEF_MAJOR_TYPE_POSINT, n)

def cbor_bytes(b: bytes) -> bytes:
    return _cbor_head(DEF_MAJOR_TYPE_BYTES, len(b)) + b

def cbor_text(s: str) -> bytes:
    bs = s.encode('utf-8')
    return _cbor_head(DEF_MAJOR_TYPE_TEXT, len(bs)) + bs

def cbor_map(pairs: List[Tuple[bytes, bytes]]) -> bytes:
    return _cbor_head(DEF_MAJOR_TYPE_MAP, len(pairs)) + b''.join(k + v for k, v in pairs)

def cbor_array(items: List[bytes]) -> bytes:
    return _cbor_head(DEF_MAJOR_TYPE_ARRAY, len(items)) + b''.join(items)

# COSE key encodings for ES256 (alg -7), RS256 (alg -257), and Ed25519 (alg -8)
# Keys:
# Common labels: 1: kty, 3: alg
# EC2: -1: crv, -2: x, -3: y  (kty=2, crv=1 for P-256)
# OKP: -1: crv, -2: x        (kty=1 for OKP, crv=6 for Ed25519)
# RSA: -1: n, -2: e          (kty=3)

def cose_es256_pk(x: bytes, y: bytes) -> bytes:
    # Ensure 32-byte coordinates
    x = x.ljust(32, b'\x00')[:32]
    y = y.ljust(32, b'\x00')[:32]
    pairs = [
        (cbor_uint(1), cbor_uint(2)),           # kty=EC2
        (cbor_uint(3), cbor_int(-7)),           # alg=-7 (ES256)
        (cbor_int(-1), cbor_uint(1)),           # crv=P-256
        (cbor_int(-2), cbor_bytes(x)),          # x
        (cbor_int(-3), cbor_bytes(y)),          # y
    ]
    return cbor_map(pairs)

def cose_rs256_pk(n: bytes, e: bytes) -> bytes:
    # typical e=65537 -> 0x010001
    n = n.lstrip(b'\x00') or b'\x00'
    pairs = [
        (cbor_uint(1), cbor_uint(3)),           # kty=RSA
        (cbor_uint(3), cbor_int(-257)),         # alg=-257 (RS256)
        (cbor_int(-1), cbor_bytes(n)),          # n
        (cbor_int(-2), cbor_bytes(e)),          # e
    ]
    return cbor_map(pairs)

def cose_eddsa_pk(x: bytes) -> bytes:
    x = x.ljust(32, b'\x00')[:32]
    pairs = [
        (cbor_uint(1), cbor_uint(1)),           # kty=OKP
        (cbor_uint(3), cbor_int(-8)),           # alg=-8 (EdDSA/Ed25519)
        (cbor_int(-1), cbor_uint(6)),           # crv=6 (Ed25519)
        (cbor_int(-2), cbor_bytes(x)),          # x
    ]
    return cbor_map(pairs)

# Minimal helper for negative integers in CBOR

def cbor_int(n: int) -> bytes:
    if n >= 0:
        return cbor_uint(n)
    m = -1 - n
    # major type 1 for negative: value encodes -(n+1)
    return _cbor_head(1, m)

# Build attestedCredentialData

def build_attested_credential(rng: random.Random) -> bytes:
    # AAGUID 16 bytes
    aaguid = bytes(rng.getrandbits(8) for _ in range(16))
    # credential ID length between 16 and 64
    cred_len = rng.randint(16, 64)
    cred_id = bytes(rng.getrandbits(8) for _ in range(cred_len))
    # Choose a COSE key type
    choice = rng.choice(['es256', 'rs256', 'eddsa'])
    if choice == 'es256':
        x = bytes(rng.getrandbits(8) for _ in range(32))
        y = bytes(rng.getrandbits(8) for _ in range(32))
        cose = cose_es256_pk(x, y)
    elif choice == 'rs256':
        # 2048-bit modulus-ish length (256 bytes), random but non-zero first byte
        n = bytearray(bytes(rng.getrandbits(8) for _ in range(256)))
        if n[0] == 0:
            n[0] = 1
        e = b"\x01\x00\x01"  # 65537
        cose = cose_rs256_pk(bytes(n), e)
    else:
        x = bytes(rng.getrandbits(8) for _ in range(32))
        cose = cose_eddsa_pk(x)
    return aaguid + struct.pack('>H', cred_len) + cred_id + cose

# Build simple extensions: a CBOR map with a couple of entries

def build_extensions(rng: random.Random) -> bytes:
    pairs = []
    # credBlob: random small bytes (<= 32)
    if rng.random() < 0.7:
        blob_len = rng.randint(1, 32)
        pairs.append((cbor_text('credBlob'), cbor_bytes(bytes(rng.getrandbits(8) for _ in range(blob_len)))))
    # hmac-secret: true
    if rng.random() < 0.7:
        # boolean true is simple value 0xF5 in CBOR
        pairs.append((cbor_text('hmac-secret'), bytes([0xF5])))
    # largeBlobKey: true
    if rng.random() < 0.4:
        pairs.append((cbor_text('largeBlobKey'), bytes([0xF5])))
    return cbor_map(pairs)

# rpIdHash helper

def pick_rp_id_and_hash(rng: random.Random) -> bytes:
    # Choose from a few domains or synthesize
    domains = [
        'example.com',
        'webauthn.io',
        'login.test',
        'auth.local',
        'fido.example'
    ]
    rp = rng.choice(domains)
    return hashlib.sha256(rp.encode('utf-8')).digest()


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    rp_hash = pick_rp_id_and_hash(rng)

    # Flags: always set UP. Randomly set UV. Optionally AT and ED.
    flags = 0x01
    if rng.random() < 0.5:
        flags |= 0x04
    include_at = rng.random() < 0.8
    include_ed = rng.random() < 0.5
    if include_at:
        flags |= 0x40
    if include_ed:
        flags |= 0x80

    # signCount: vary across typical values
    signcount_choices = [0, 1, 2, 5, 0xFFFFFFFF]
    if rng.random() < 0.6:
        sc = rng.choice(signcount_choices)
    else:
        sc = rng.randint(0, 100000)
    sign_count = struct.pack('>I', sc)

    body = b''
    if include_at:
        body += build_attested_credential(rng)
    if include_ed:
        body += build_extensions(rng)

    authdata = rp_hash + bytes([flags]) + sign_count + body
    # Keep within 4096 bytes
    return authdata[:4096]

import os
import random
import struct
import hashlib
from typing import Tuple

# Generator for WebAuthn/CTAP authenticator data (authData) in raw wire format.
# Structure:
# authData := rpIdHash(32) || flags(1) || signCount(4) || [attestedCredentialData] || [extensions]
# If attestedCredentialData present: flags bit AT (0x40) must be set and the section is:
#   aaguid(16) || credIdLen(2 big-endian) || credId(credIdLen) || coseKey(CBOR)
# If extensions present: flags bit ED (0x80) must be set and a CBOR map follows.
# We keep COSE key and extension CBOR minimal but well-formed.

# Minimal CBOR helpers (only what we need)

def _cbor_uint(n: int) -> bytes:
    if n < 0:
        raise ValueError("negative not supported here")
    # Major type 0
    if n <= 23:
        return bytes([0x00 | n])
    elif n <= 0xFF:
        return bytes([0x18, n])
    elif n <= 0xFFFF:
        return bytes([0x19]) + struct.pack('>H', n)
    elif n <= 0xFFFFFFFF:
        return bytes([0x1a]) + struct.pack('>I', n)
    else:
        return bytes([0x1b]) + struct.pack('>Q', n)


def _cbor_negint(n: int) -> bytes:
    # Major type 1, encodes -1-n
    if n >= 0:
        raise ValueError("use _cbor_uint for non-negative")
    m = -1 - n
    if m <= 23:
        return bytes([0x20 | m])
    elif m <= 0xFF:
        return bytes([0x38, m])
    elif m <= 0xFFFF:
        return bytes([0x39]) + struct.pack('>H', m)
    elif m <= 0xFFFFFFFF:
        return bytes([0x3a]) + struct.pack('>I', m)
    else:
        return bytes([0x3b]) + struct.pack('>Q', m)


def _cbor_bytes(b: bytes) -> bytes:
    l = len(b)
    # Major type 2
    if l <= 23:
        return bytes([0x40 | l]) + b
    elif l <= 0xFF:
        return bytes([0x58, l]) + b
    elif l <= 0xFFFF:
        return bytes([0x59]) + struct.pack('>H', l) + b
    elif l <= 0xFFFFFFFF:
        return bytes([0x5a]) + struct.pack('>I', l) + b
    else:
        return bytes([0x5b]) + struct.pack('>Q', l) + b


def _cbor_text(s: str) -> bytes:
    b = s.encode('utf-8')
    l = len(b)
    # Major type 3
    if l <= 23:
        return bytes([0x60 | l]) + b
    elif l <= 0xFF:
        return bytes([0x78, l]) + b
    elif l <= 0xFFFF:
        return bytes([0x79]) + struct.pack('>H', l) + b
    elif l <= 0xFFFFFFFF:
        return bytes([0x7a]) + struct.pack('>I', l) + b
    else:
        return bytes([0x7b]) + struct.pack('>Q', l) + b


def _cbor_map_start(n: int) -> bytes:
    # Major type 5
    if n <= 23:
        return bytes([0xa0 | n])
    elif n <= 0xFF:
        return bytes([0xb8, n])
    elif n <= 0xFFFF:
        return bytes([0xb9]) + struct.pack('>H', n)
    elif n <= 0xFFFFFFFF:
        return bytes([0xba]) + struct.pack('>I', n)
    else:
        return bytes([0xbb]) + struct.pack('>Q', n)


def _cbor_array_start(n: int) -> bytes:
    # Major type 4
    if n <= 23:
        return bytes([0x80 | n])
    elif n <= 0xFF:
        return bytes([0x98, n])
    elif n <= 0xFFFF:
        return bytes([0x99]) + struct.pack('>H', n)
    elif n <= 0xFFFFFFFF:
        return bytes([0x9a]) + struct.pack('>I', n)
    else:
        return bytes([0x9b]) + struct.pack('>Q', n)


# COSE key generators for ES256, ES384, Ed25519, and RSA (RS256 public-only minimal)
# COSE key common labels: 1:kty, 3:alg, -1:crv, -2:x, -3:y for EC2; -2:n, -3:e for RSA;
# For OKP (Ed25519): 1:kty=1(OKP), 3:alg=-8(EdDSA), -1:crv=6(Ed25519), -2:x


def _cose_ec2_key(curve: int, alg: int, x: bytes, y: bytes) -> bytes:
    # Map with 5 pairs
    m = _cbor_map_start(5)
    m += _cbor_uint(1) + _cbor_uint(2)  # kty = EC2
    m += _cbor_uint(3) + (_cbor_negint(alg) if alg < 0 else _cbor_uint(alg))
    m += _cbor_negint(-1) + _cbor_uint(curve)
    m += _cbor_negint(-2) + _cbor_bytes(x)
    m += _cbor_negint(-3) + _cbor_bytes(y)
    return m


def _cose_okp_key(curve: int, alg: int, x: bytes) -> bytes:
    m = _cbor_map_start(4)
    m += _cbor_uint(1) + _cbor_uint(1)  # kty=OKP
    m += _cbor_uint(3) + (_cbor_negint(alg) if alg < 0 else _cbor_uint(alg))
    m += _cbor_negint(-1) + _cbor_uint(curve)
    m += _cbor_negint(-2) + _cbor_bytes(x)
    return m


def _cose_rsa_key(n: bytes, e: bytes, alg: int = -257) -> bytes:
    # Minimal public key: kty=3 (RSA), alg=-257 (RS256), n, e
    m = _cbor_map_start(4)
    m += _cbor_uint(1) + _cbor_uint(3)  # kty=RSA
    m += _cbor_uint(3) + _cbor_negint(alg)
    m += _cbor_negint(-1) + _cbor_bytes(n)
    m += _cbor_negint(-2) + _cbor_bytes(e)
    return m


def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))


def _rp_id_hash_for(rp_id: str) -> bytes:
    return hashlib.sha256(rp_id.encode('utf-8')).digest()


def _make_attested_cred(rng: random.Random, cose_choice: int) -> bytes:
    # aaguid 16 bytes
    aaguid = _rand_bytes(rng, 16)
    # credId length and bytes
    cred_len = rng.randint(16, 64)
    cred_id = _rand_bytes(rng, cred_len)

    # Choose COSE public key encoding
    if cose_choice == 0:
        # ES256: crv=1, alg=-7, x/y 32 bytes
        x = _rand_bytes(rng, 32)
        y = _rand_bytes(rng, 32)
        cose = _cose_ec2_key(curve=1, alg=-7, x=x, y=y)
    elif cose_choice == 1:
        # ES384: crv=2, alg=-35, x/y 48 bytes
        x = _rand_bytes(rng, 48)
        y = _rand_bytes(rng, 48)
        cose = _cose_ec2_key(curve=2, alg=-35, x=x, y=y)
    elif cose_choice == 2:
        # Ed25519: OKP crv=6, alg=-8, x 32 bytes
        x = _rand_bytes(rng, 32)
        cose = _cose_okp_key(curve=6, alg=-8, x=x)
    else:
        # RS256: modulus ~2048 bits, exponent 0x010001
        # Generate pseudo modulus bytes with high bit set, avoid leading zeros
        n = bytearray(_rand_bytes(rng, 256))
        n[0] |= 0x80
        e = b"\x01\x00\x01"
        cose = _cose_rsa_key(bytes(n), e, alg=-257)

    body = aaguid + struct.pack('>H', cred_len) + cred_id + cose
    return body


def _make_extensions(rng: random.Random) -> bytes:
    # Build a small CBOR map of 1-3 extensions with simple values
    entries = []
    # Randomly decide which extensions to include
    # Examples: credBlob (bytes), largeBlobKey (bytes), hmac-secret (bool), extA (int)
    if rng.random() < 0.7:
        # credBlob
        blob_len = rng.randint(1, 64)
        entries.append((_cbor_text("credBlob"), _cbor_bytes(_rand_bytes(rng, blob_len))))
    if rng.random() < 0.5:
        # hmac-secret
        entries.append((_cbor_text("hmac-secret"), bytes([0xf5])))  # true
    if rng.random() < 0.4:
        # largeBlobKey
        entries.append((_cbor_text("largeBlobKey"), _cbor_bytes(_rand_bytes(rng, 32))))
    if rng.random() < 0.3:
        # arbitrary numeric extension
        entries.append((_cbor_text("extA"), _cbor_uint(rng.randint(0, 1000))))

    if not entries:
        # Ensure at least one
        entries.append((_cbor_text("hmac-secret"), bytes([0xf4 if rng.random() < 0.5 else 0xf5])))

    m = _cbor_map_start(len(entries))
    for k, v in entries:
        m += k + v
    return m


def _build_authdata(rng: random.Random) -> bytes:
    # rpId selection
    rp_candidates = [
        "example.com", "webauthn.io", "localhost", "fido.test", "corp.example", "test.invalid"
    ]
    rp = rng.choice(rp_candidates)
    rp_hash = _rp_id_hash_for(rp)

    # Flags assembly
    UP = 0x01
    UV = 0x04
    AT = 0x40
    ED = 0x80

    want_at = rng.random() < 0.85  # frequently include attested cred data
    want_ed = rng.random() < 0.5   # sometimes include extensions

    flags = UP
    if rng.random() < 0.5:
        flags |= UV
    if want_at:
        flags |= AT
    if want_ed:
        flags |= ED

    # signCount can be 0..random range
    sign_count = rng.randint(0, 500000)

    buf = bytearray()
    buf += rp_hash
    buf.append(flags)
    buf += struct.pack('>I', sign_count)

    if want_at:
        cose_choice = rng.randint(0, 3)
        buf += _make_attested_cred(rng, cose_choice)

    if want_ed:
        buf += _make_extensions(rng)

    return bytes(buf)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Create between 1 and 3 concatenated authData blobs to exercise stubs that may take arbitrary strings
    count = rng.randint(1, 2)  # keep size modest
    parts = []
    total = 0
    for _ in range(count):
        ad = _build_authdata(rng)
        parts.append(ad)
        total += len(ad)
        if total > 3500:
            break
    data = b"".join(parts)
    # Ensure non-empty and within 4096 bytes
    if not data:
        data = _build_authdata(rng)
    return data[:4096]

import json
import os
import random
import base64
from typing import Dict, Any

# Generator for WebAuthn clientData JSON buffers
# Target stubs call fido_assert_set_clientdata and fido_cred_set_clientdata with a non-empty buffer
# Provide well-formed, UTF-8 JSON that matches WebAuthn expectations and vary content with a seed.

WEBAUTHN_TYPES = [
    "webauthn.create",
    "webauthn.get",
]

# Reasonable origins to exercise parsing paths
ORIGINS = [
    "https://example.com",
    "https://sub.example.com:8443",
    "https://localhost",
    "http://intranet.local",
    "https://xn--bcher-kva.example",  # punycode
]

# Additional optional fields commonly seen in clientDataJSON
EXTRA_FIELD_KEYS = [
    "crossOrigin",
    "topOrigin",
    "tokenBinding",
    "androidPackageName",
    "clientExtensions",
    "sameOriginWithAncestor",
]


def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))


def _b64url_no_pad(b: bytes) -> str:
    return base64.urlsafe_b64encode(b).rstrip(b"=").decode("ascii")


def _maybe(rng: random.Random, p: float = 0.5) -> bool:
    return rng.random() < p


def _build_token_binding(rng: random.Random) -> Dict[str, Any]:
    # tokenBinding: { id: b64url, status: "present"|"supported" }
    status = rng.choice(["present", "supported"]) if _maybe(rng, 0.8) else "not-supported"
    tb: Dict[str, Any] = {"status": status}
    if status in ("present", "supported") and _maybe(rng, 0.7):
        tb["id"] = _b64url_no_pad(_rand_bytes(rng, rng.randrange(8, 33)))
    return tb


def _random_origin(rng: random.Random) -> str:
    base = rng.choice(ORIGINS)
    # Optionally add a path/query to keep it valid but varied
    path_segments = ["", "", "/webauthn", "/login", "/auth/finish"]
    base += rng.choice(path_segments)
    if _maybe(rng, 0.3):
        base += "?" + rng.choice(["a=1", "challenge=1", "x=y"])  # query is allowed in originlike URL strings sometimes used
    return base


def _random_extensions(rng: random.Random) -> Dict[str, Any]:
    # Create a small, valid extensions object to increase coverage
    ext: Dict[str, Any] = {}
    if _maybe(rng, 0.7):
        ext["credProps"] = {"rk": rng.choice([True, False])}
    if _maybe(rng, 0.5):
        ext["prf"] = {"enabled": rng.choice([True, False])}
    if _maybe(rng, 0.5):
        ext["largeBlob"] = {"support": rng.choice(["required", "preferred", "discouraged"]) }
    return ext


def _build_client_data(rng: random.Random) -> Dict[str, Any]:
    t = rng.choice(WEBAUTHN_TYPES)
    # Challenges are random bytes encoded as base64url without padding
    # Keep sizes reasonable (16..64)
    ch_len = rng.randrange(16, 65)
    challenge = _b64url_no_pad(_rand_bytes(rng, ch_len))

    obj: Dict[str, Any] = {
        "type": t,
        "challenge": challenge,
        "origin": _random_origin(rng),
    }

    # Optionally include topOrigin (useful for cross-origin scenarios)
    if _maybe(rng, 0.4):
        obj["topOrigin"] = _random_origin(rng)

    # crossOrigin boolean (commonly found)
    if _maybe(rng, 0.6):
        obj["crossOrigin"] = rng.choice([True, False])

    # tokenBinding object
    if _maybe(rng, 0.4):
        obj["tokenBinding"] = _build_token_binding(rng)

    # androidPackageName (platform specific)
    if _maybe(rng, 0.2):
        obj["androidPackageName"] = rng.choice([
            "com.example.app",
            "org.example.webauthn",
            "com.company.product",
        ])

    # clientExtensions (arbitrary object)
    if _maybe(rng, 0.5):
        obj["clientExtensions"] = _random_extensions(rng)

    # sameOriginWithAncestor (WebKit historical)
    if _maybe(rng, 0.2):
        obj["sameOriginWithAncestor"] = rng.choice([True, False])

    # Optionally add a few arbitrary but JSON-safe custom fields to vary structure
    if _maybe(rng, 0.3):
        obj["_ua"] = rng.choice([
            "Mozilla/5.0", "Chrome/121.0", "Safari/17.0", "Edge/120.0"
        ])
    if _maybe(rng, 0.3):
        obj["_ts"] = int(rng.random() * 2**31)

    return obj


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Build a valid clientData JSON object and serialize as UTF-8, compact
    cd_obj = _build_client_data(rng)

    # Ensure the total size stays <= 4096 bytes. If it exceeds, trim optional fields deterministically.
    def encode(o: Dict[str, Any]) -> bytes:
        return json.dumps(o, separators=(",", ":"), ensure_ascii=False).encode("utf-8")

    data = encode(cd_obj)
    if len(data) > 4096:
        # Drop least important/optional fields in a fixed order until under limit
        for k in [
            "_ua", "_ts", "clientExtensions", "androidPackageName",
            "tokenBinding", "topOrigin"
        ]:
            if k in cd_obj:
                del cd_obj[k]
                data = encode(cd_obj)
                if len(data) <= 4096:
                    break
        # As a last resort, shorten challenge
        if len(data) > 4096 and isinstance(cd_obj.get("challenge"), str):
            cd_obj["challenge"] = cd_obj["challenge"][:32]
            data = encode(cd_obj)

    # Guarantee non-empty per stub requirement
    if not data:
        data = b"{}"

    return data

import os
import random
import struct
from typing import List

# We need to generate valid assertion signature buffers. The fuzz stubs only
# require that the signature buffer be non-empty; they do not parse/verify it.
# However, to exercise different internal code paths that may expect realistic
# encodings, we produce plausible signatures for common algorithms used by
# WebAuthn/FIDO:
# - ECDSA (ES256/ES384): ASN.1 DER-encoded SEQUENCE of two INTEGERs (r, s)
# - RSA PKCS#1 v1.5 (RS256): raw signature bytes of key size (e.g., 256 bytes)
# - EdDSA (Ed25519): raw 64-byte signature
# We randomize among these and include edge-case yet valid sizes (e.g., small
# INTEGER leading zeros for DER canonical form) while keeping total size <=4096.

# Helper: minimal ASN.1 DER encoding for ECDSA signature
# SEQUENCE { INTEGER r; INTEGER s; }
# INTEGER is encoded as: 0x02, len, bytes (two's complement; add 0x00 if MSB set)

def _int_to_der_integer(x_bytes: bytes) -> bytes:
    # Strip leading zeros
    x = x_bytes.lstrip(b"\x00") or b"\x00"
    # If high bit set, prepend 0x00 to ensure positive integer
    if x[0] & 0x80:
        x = b"\x00" + x
    return b"\x02" + _der_len(len(x)) + x


def _der_len(n: int) -> bytes:
    if n < 0x80:
        return bytes([n])
    # long form
    out = []
    while n > 0:
        out.append(n & 0xFF)
        n >>= 8
    out.reverse()
    return bytes([0x80 | len(out)] + out)


def gen_ecdsa_der_signature(rng: random.Random, bits: int) -> bytes:
    # bits: 256 for ES256, 384 for ES384
    bytelen = bits // 8
    # Generate r and s as random non-zero integers of up to bytelen bytes
    def gen_scalar():
        # allow varying effective lengths (1..bytelen) to explore DER lengths
        eff = rng.randint(1, bytelen)
        # ensure non-zero
        b = bytearray(rng.getrandbits(8) for _ in range(eff))
        if all(v == 0 for v in b):
            b[-1] = 1
        return bytes(b)

    r = gen_scalar()
    s = gen_scalar()
    der_r = _int_to_der_integer(r)
    der_s = _int_to_der_integer(s)
    seq_body = der_r + der_s
    der = b"\x30" + _der_len(len(seq_body)) + seq_body
    return der


def gen_rsa_pkcs1_signature(rng: random.Random, bits: int = 2048) -> bytes:
    # Raw signature of modulus size; random bytes
    size = bits // 8
    sig = bytearray(rng.getrandbits(8) for _ in range(size))
    # Avoid all-zero (still valid but keep non-empty constraint anyway)
    if all(v == 0 for v in sig):
        sig[-1] = 1
    return bytes(sig)


def gen_eddsa_signature(rng: random.Random) -> bytes:
    # Ed25519 signatures are 64 bytes (R[32] || S[32])
    sig = bytearray(rng.getrandbits(8) for _ in range(64))
    if all(v == 0 for v in sig):
        sig[-1] = 1
    return bytes(sig)


def gen_misc_small_nonempty(rng: random.Random) -> bytes:
    # Occasionally return small yet non-empty buffers to exercise minimal cases
    n = rng.randint(1, 16)
    return bytes(rng.getrandbits(8) for _ in range(n))


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose a signature style
    choice = rng.choices(
        population=["es256", "es384", "rs256", "eddsa", "small"],
        weights=[35, 15, 25, 20, 5],
        k=1,
    )[0]

    if choice == "es256":
        sig = gen_ecdsa_der_signature(rng, 256)
    elif choice == "es384":
        sig = gen_ecdsa_der_signature(rng, 384)
    elif choice == "rs256":
        sig = gen_rsa_pkcs1_signature(rng, 2048)
    elif choice == "eddsa":
        sig = gen_eddsa_signature(rng)
    else:
        sig = gen_misc_small_nonempty(rng)

    # Ensure <= 4096 bytes (all generators already are), and non-empty
    if not sig:
        sig = b"\x01"

    return sig
